def md_to_html(md_text):
    """Convert markdown chapter content to HTML paragraphs."""
    lines = md_text.split('\n')
    html_lines = []
    in_list = False

    for line in lines:
        stripped = line.strip()
        if not stripped:
            if in_list:
                html_lines.append('</ul>')
                in_list = False
            continue
        if stripped.startswith('## ') or stripped.startswith('# '):
            continue  # Skip header
        if stripped.startswith('*') and stripped.endswith('*') and not stripped.startswith('**'):
            html_lines.append(f'<blockquote><p>{stripped.strip("*")}</p></blockquote>')
        elif stripped.startswith('- '):
            if not in_list:
                html_lines.append('<ul>')
                in_list = True
            html_lines.append(f'<li>{stripped[2:]}</li>')
        elif stripped.startswith('* * *') or stripped.startswith('---'):
            html_lines.append('<p class="scene-break">* * *</p>')
        else:
            if in_list:
                html_lines.append('</ul>')
                in_list = False
            html_lines.append(f'<p>{stripped}</p>')

    if in_list:
        html_lines.append('</ul>')

    return '\n'.join(html_lines)

def build_book_html(chapters_data, title, series_name, book_num):
    """Build complete book HTML from chapter data."""
    chapters_data = sorted(chapters_data, key=lambda x: x[0])

    # TOC rows
    toc_rows = []
    toc_entries = []
    for i, (ch_num, content) in enumerate(chapters_data, 1):
        # Extract title from content
        title_match = re.search(r'[——-]\s*(.+?)$', content.split('\n')[0]) if content.strip() else None
        ch_title = title_match.group(1).strip() if title_match else f"Chapter {ch_num}"
        toc_entries.append(ch_title)
        # Find sub-title if present
        sub_title = ''
        if '—' in content.split('\n')[0]:
            sub_title = content.split('\n')[0].split('—')[1].strip() if '—' in content.split('\n')[0] else ''
        elif '--' in content.split('\n')[0]:
            sub_title = content.split('\n')[0].split('--')[1].strip()

        toc_rows.append(f'<tr><td class="num">{i}.</td><td class="title">{ch_title}</td><td class="dots">{"·" * 40}</td><td class="page">PAGE</td></tr>')

    # Chapter content
    ch_content = []
    for i, (ch_num, content) in enumerate(chapters_data, 1):
        # Extract title from content header
        first_line = content.split('\n')[0]
        title_match = re.search(r'[——-]\s*(.+?)$', first_line)
        ch_title = title_match.group(1).strip() if title_match else f"Chapter {i}"

        # Remove the header line from content
        body = '\n'.join(content.split('\n')[1:]).strip()
        body_html = md_to_html(body)

        ch_content.append(f'<h1 class="chapter-title" id="ch{i}">Chapter {i} — {ch_title}</h1>')
        ch_content.append(body_html)

    # Estimate pages for TOC
    total_words = sum(len(c[1].split()) for c in chapters_data)

    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{title}</title>
<style>
{CSS}
</style>
</head>
<body>

